import React from 'react';
import { Box, Container } from '@mui/material';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import carouselBg from '../assets/Carousel.png';

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    arrows: true,
  };

  const slides = [1, 2, 3, 4, 5]; // Dinamik veriyle değiştirilebilir

  return (
    <Box
      sx={{
        backgroundImage: `url(${carouselBg})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        width: '100%',
        minHeight: '500px',
        py: 8,
        position: 'relative',
      }}
    >
      <Container
        maxWidth="md"
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1,
        }}
      >
        <Slider {...settings}>
          {slides.map((item) => (
            <Box
              key={item}
              sx={{
                px: 1,
                py: 1,
              }}
            >
              <Box
                sx={{
                  backgroundColor: '#fff',
                  borderRadius: '12px',
                  overflow: 'hidden',
                  p: 2,
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                  transition: 'transform 0.3s ease',
                  maxWidth: { xs: '100%', md: '800px' },
                  margin: '0 auto',
                  '&:hover': {
                    transform: 'translateY(-5px)',
                  },
                }}
              >
                <Box
                  component="img"
                  src={`https://via.placeholder.com/400x300?text=Slide+${item}`}
                  alt={`Slide ${item}`}
                  sx={{
                    width: '100%',
                    height: 'auto',
                    borderRadius: '8px',
                    display: 'block',
                  }}
                />
              </Box>
            </Box>
          ))}
        </Slider>
      </Container>
    </Box>
  );
};

export default EventsSlider;
